package javacore;

public class operator {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a= 25, b=30;
		System.out.println(a+b);
		System.out.println(a-b);
		System.out.println(b%a);
		System.out.println(b/a);
		
		int marks =62;
		System.out.println(marks>90&&marks<=100);
		System.out.println(marks>90||marks<=100);
		System.out.println(marks==100);
		System.out.println(marks!=100);
		
	}

}
